import heapq

class DonguHatasi(ValueError):
    def __init__(self, dongu: list[str]):
        self.dongu = dongu
        super().__init__(f"Döngü tespit edildi: {dongu}")

def kurulum_sirasi(deps: dict[str, list[str]]) -> list[str]:
    # Tüm paketleri belirle (anahtarlar ve bağımlılıklar)
    all_nodes = set(deps.keys())
    for d_list in deps.values():
        for d in d_list:
            all_nodes.add(d)

    # Adjacency list: dependency -> package (edge direction for topological sort)
    adj = {node: [] for node in all_nodes}
    in_degree = {node: 0 for node in all_nodes}

    for pkg, dependencies in deps.items():
        unique_deps = set(dependencies)
        for dep in unique_deps:
            adj[dep].append(pkg)
            in_degree[pkg] += 1

    # Kahn's algorithm (Topological Sort) with Priority Queue for lexicographical order
    queue = [node for node in all_nodes if in_degree[node] == 0]
    heapq.heapify(queue)

    result = []
    while queue:
        u = heapq.heappop(queue)
        result.append(u)
        for v in adj[u]:
            in_degree[v] -= 1
            if in_degree[v] == 0:
                heapq.heappush(queue, v)

    # Döngü kontrolü
    if len(result) < len(all_nodes):
        remaining_nodes = [node for node in all_nodes if in_degree[node] > 0]
        visited = set()
        path = []
        path_set = set()

        def find_cycle(u):
            if u in path_set:
                cycle_start_idx = path.index(u)
                return path[cycle_start_idx:]
            if u in visited:
                return None

            visited.add(u)
            path.append(u)
            path_set.add(u)

            for v in adj[u]:
                if in_degree[v] > 0:
                    res = find_cycle(v)
                    if res: return res

            path.pop()
            path_set.remove(u)
            return None

        found_cycle = []
        for node in remaining_nodes:
            # DFS ile döngü elemanlarını bulmak için her düğümü tek tek dene
            visited = set() # Her denemede temizle ki tüm graf taranabilsin
            path = []
            path_set = set()
            found_cycle = find_cycle(node)
            if found_cycle:
                break

        if not found_cycle:
            # Kendine bağımlı durumlar için (x -> x)
            for node in remaining_nodes:
                if node in deps and node in deps[node]:
                    found_cycle = [node]
                    break

        if found_cycle:
            min_val = min(found_cycle)
            idx = found_cycle.index(min_val)
            normalized_cycle = found_cycle[idx:] + found_cycle[:idx]
            raise DonguHatasi(normalized_cycle)

    return result
